module top_module(
  input CLK,
  input DIN,
  input READ,
  input SHIFT,
  output reg DOUT
);localparam MAX_DNA_BITS = 96;
  localparam MSB_DNA_BITS = MAX_DNA_BITS - 1;

  reg [MSB_DNA_BITS:0] dna_val;

  always @(posedge CLK) begin
    if (READ) begin
      dna_val <= DIN;
      DOUT <= dna_val[MSB_DNA_BITS];
    end else if (SHIFT) begin
      dna_val <= {dna_val[MSB_DNA_BITS-1:0], DIN};
      DOUT <= dna_val[MSB_DNA_BITS];
    end
  end

endmodule

