module top_module(PAD, PADIN, PADOUT, PADOEN);inout PAD;
  output PADIN;
  input PADOEN;
  input PADOUT;
  reg drive_en;
  reg PAD_reg; // Declare a reg to hold the value of PAD

  assign PAD = (drive_en) ? PADIN : 1'bz; // Drive PAD based on drive_en
  assign PADOUT = PAD_reg; // Assign the output of PAD_reg to PADOUT

  always @(posedge PADOEN) begin
    if (PADOEN == 1'b1) begin
      drive_en <= 1'b1;
    end else begin
      drive_en <= 1'b0;
      PAD_reg <= 1'bz; // Use PAD_reg instead of PAD
    end
  end

  // Output the correct value to PAD_reg when drive_en is high
  always @* begin
    if (drive_en) begin
      PAD_reg = PADIN; // When enabled, drive with PADIN
    end else begin
      PAD_reg = 1'bz; // Otherwise high impedance
    end
  end
endmodule

