description:
Design a circuit that implements a left shift operation on a 16-bit input. The module continuously shifts the input left by 4 bits while operating under a clock signal, and it is capable of handling an input reset. The shifting operation only occurs after the input has been received for ten clock cycles; prior to that, the module counts clock cycles and maintains the input value. Once the shifting begins, the output reflects the shifted value, and a valid signal is asserted to indicate that the output is ready.
module top_module(/*AUTOARG*/
   // Outputs
   out,
   valid,
   // Inputs
   clk, reset, in
   );

code:
module top_module(/*AUTOARG*/
   // Outputs
   out,
   valid,
   // Inputs
   clk, reset, in
   );input clk;
   input reset;
   input [15:0] in;
   output [15:0] out;
   output valid;

   reg [3:0] count;
   reg [15:0] shifted_in;
   reg [15:0] shifted_out;
   reg valid_reg;

   always @(posedge clk) begin
      if (reset) begin
         count <= 4'b0;
         shifted_in <= 16'h0;
         shifted_out <= 16'h0;
         valid_reg <= 1'b0;
      end
      else begin
         if (count < 4'b1010) begin
            count <= count + 1;
            shifted_in <= in;
            shifted_out <= 16'h0;
            valid_reg <= 1'b0;
         end
         else begin
            shifted_out <= {in[11:0], 4'b0};
            valid_reg <= 1'b1;
            if (count == 4'b1010) begin
               shifted_in <= in;
            end
            count <= count + 1;
         end
      end
   end

   assign out = shifted_out;
   assign valid = valid_reg;

endmodule

