wire out_and_inv_oe = out & ~oe;
wire out_and_inv_in = out & inv_in;
wire out_and_oe_and_in = out & oe_and_in;
wire out_mux = oe_and_inv_in | out_and_oe_and_in;
assign out = out_mux | out_and_inv_oe;

