wire outb_and_inv_oe = outb & ~oe;
wire outb_and_in = outb & in;
wire outb_and_oe_and_inv_in = outb & oe_and_inv_in;
wire outb_mux = oe_and_in | outb_and_oe_and_inv_in;
assign outb = outb_mux | outb_and_inv_oe;

endmodule

