description:
Design a multi-function ALU control unit that generates a 3-bit output operation code (OP) based on the input ALU operation mode (ALUOp) and function code (FUNC). The module distinguishes between different operation types, including load/store, branch equal (BEQ), and R-type instructions, to output appropriate control signals for addition, subtraction, logical OR, and NOR operations. The logic combines the ALUOp inputs with specific bits from the FUNC code to enable or disable various operations based on the instruction type. This functionality is critical for directing an ALU's behavior in a processing unit.
module top_module(
	ALUOp,	
	FUNC,		
	OP			
);

code:
module top_module(
	ALUOp,	
	FUNC,		
	OP			
);input wire  [1:0] ALUOp;
	input wire  [5:0] FUNC;
	output wire [2:0] OP;

	wire LS, BEQ, R;
	wire OP_ADD, OP_SUB, OP_AND, OP_OR, OP_SLT;

	assign LS  = ~ALUOp[0] & ~ALUOp[1];
	assign BEQ =  ALUOp[0] & ~ALUOp[1];
	assign R   = ~ALUOp[0] &  ALUOp[1];

	assign OP_ADD = LS  | (FUNC[5] & ~FUNC[4] & ~FUNC[3] & ~FUNC[2] & ~FUNC[1] & ~FUNC[0] & R);
	assign OP_SUB = BEQ | (FUNC[5] & ~FUNC[4] & ~FUNC[3] & ~FUNC[2] &  FUNC[1] & ~FUNC[0] & R);

	assign OP_OR  = FUNC[5] & ~FUNC[4] & ~FUNC[3] &  FUNC[2] & ~FUNC[1] &  FUNC[0] & R;
	assign OP_NOR = FUNC[5] & ~FUNC[4] & ~FUNC[3] &  FUNC[2] &  FUNC[1] &  FUNC[0] & R;

	assign OP[2] =  OP_SUB | OP_NOR;
	assign OP[1] =  OP_ADD | OP_SUB;
	assign OP[0] =  OP_OR;


endmodule

