module top_module(
    input din,
    input mainclk,
    input updateclk,
    input capture,
    input update,
    output reg dout
);parameter TOTAL_REG = 202;

reg dout_tmp;
reg generator_reg [TOTAL_REG - 1:0];
reg update_reg [TOTAL_REG - 1:0];
integer i;

initial begin
    dout_tmp <= 1'b0;
    for (i = 0; i < TOTAL_REG; i = i + 1) begin
        generator_reg [i] <= 1'b0;
        update_reg [i] <= 1'b0;
    end
end

always @(posedge mainclk) begin
    if ((capture == 1'b0) && (update == 1'b1)) begin
        for (i = 0; i < TOTAL_REG; i = i + 1) begin
            generator_reg[i] <= update_reg[i];
        end
    end
end

always @(posedge updateclk) begin
    dout_tmp <= update_reg[TOTAL_REG - 1];

    if ((capture == 1'b0) && (update == 1'b0)) begin
        for (i = (TOTAL_REG - 1); i > 0; i = i - 1) begin
            update_reg[i] <= update_reg[i - 1];
        end
        update_reg[0] <= din; 
    end else if ((capture == 1'b1) && (update == 1'b0)) begin
        for (i = 0; i < TOTAL_REG; i = i + 1) begin
            update_reg[i] <= generator_reg[i];
        end
    end
end

assign dout = dout_tmp;

endmodule

