      led <= 1'b0;
    end else begin
      if (valid_a && ready_b) begin
        if (select) begin
          shift_reg <= {shift_reg[98:0], data_in};
          shift_out <= shift_reg[99:92];
          data_out <= 32'b0;
          valid_b <= 1'b1;
          // ready_a cannot be assigned here as it is a wire
          if (count == 6'b111111) begin
            led <= 1'b1;
            count <= 6'b0;
          end else begin
            count <= count + 1;
          end
        end else begin
          accumulator <= accumulator + data_in;
          data_out <= accumulator;
          shift_out <= 8'b0;
          valid_b <= 1'b1;
          // ready_a cannot be assigned here as it is a wire
          if (count == 6'b111111) begin
            led <= 1'b1;
            count <= 6'b0;
          end else begin
            count <= count + 1;
          end
        end
      end else begin
        valid_b <= 1'b0;
      end
    end
  end

  assign ready_a = ~valid_a || ready_b; // This keeps ready_a as a wire assignment

endmodule

