module top_module(
  input vclock,
  output reg [10:0] hcount,
  output reg [9:0] vcount,
  output reg vsync,
  output reg hsync,
  output reg blank
);// horizontal timing constants
  localparam H_DISPLAY = 1024;
  localparam H_FRONT_PORCH = 16;
  localparam H_SYNC_WIDTH = 96;
  localparam H_TOTAL = 1344;

  // vertical timing constants
  localparam V_DISPLAY = 768;
  localparam V_FRONT_PORCH = 29;
  localparam V_SYNC_WIDTH = 2;
  localparam V_TOTAL = 806;

  // horizontal signals
  wire hsync_on = (hcount == H_DISPLAY + H_FRONT_PORCH);
  wire hsync_off = (hcount == H_TOTAL - 1);
  wire hblank_on = (hcount >= H_DISPLAY && hcount < H_TOTAL);

  // vertical signals
  wire vsync_on = (vcount == V_DISPLAY + V_FRONT_PORCH);
  wire vsync_off = (vcount == V_TOTAL - 1);
  wire vblank_on = (vcount >= V_DISPLAY && vcount < V_TOTAL);

  // sync and blanking signals
  always @(posedge vclock) begin
    if (hsync_on) begin
      hsync <= 0;
    end else if (hsync_off) begin
      hsync <= 1;
    end

    if (vsync_on) begin
      vsync <= 0;
    end else if (vsync_off) begin
      vsync <= 1;
    end

    blank <= hblank_on || vblank_on;

    if (hcount == H_TOTAL - 1) begin
      hcount <= 0;
      if (vcount == V_TOTAL - 1) begin
        vcount <= 0;
      end else begin
        vcount <= vcount + 1;
      end
    end else begin
      hcount <= hcount + 1;
    end
  end

endmodule

