    input wire X,
    output reg [31:0] count
);

code:
module top_module(
    input wire X,
    output reg [31:0] count
);reg [1:0] state;
reg [1:0] next_state;

always @ (posedge X or negedge X)
begin
    next_state[1] = X;
    next_state[0] = state[1];
    state <= next_state;
end

always @ (posedge X or negedge X)
begin
    if (state[1] != state[0])
        count <= count + 1;
end

endmodule

