module top_module(s,r,clk,q,q_bar);input s,r,clk;
output reg q,q_bar;
always@(posedge clk)
begin
if(s==0)
begin
    if(r==0)
    q=q;
    q_bar=~q;
    if(r==1)
    q=0;
    q_bar=~q;
end 
if(s==1)
begin
    if(r==0)
    q=1;
    q_bar=~q;
    if(r==1)
    q=1'bx;
    q_bar=1'bx;
end
end
endmodule

module top_module(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    input CLK,
    output reg [3:0] SUM,
    output reg OVERFLOW
);reg [3:0] temp;
    reg [4:0] temp2;
    reg carry;

    always @(posedge CLK) begin
        if (SUB) begin
            temp = A - B;
            carry = (temp[3] == 1);
        end else begin
            temp = A + B;
            carry = (temp[4] == 1);
        end

        if (carry) begin
            temp2 = {1'b1, temp};
            if (SUB) begin
                SUM = temp2[3:0];
                OVERFLOW = (temp2[4] != temp[3]);
            end else begin
                SUM = temp2[2:0];
                OVERFLOW = (temp2[4] != carry);
            end
        end else begin
            SUM = temp;
            OVERFLOW = 1'b0;
        end
    end

endmodule

