module top_module(
    input [lpm_width-1:0] d,
    input clock,
    input aclr,
    output [lpm_width-1:0] q
);// GLOBAL PARAMETER DECLARATION
parameter lpm_delay = 1;
parameter lpm_width = 64;

// INTERNAL REGISTERS DECLARATION
reg [lpm_width-1:0] dffpipe [lpm_delay:0];
reg [lpm_width-1:0] q_reg;

// LOCAL INTEGER DECLARATION
integer i;

// INITIAL CONSTRUCT BLOCK
initial begin
    for (i = 0; i <= lpm_delay; i = i + 1)
        dffpipe[i] <= 0;
    q_reg <= 0;
end

// ALWAYS CONSTRUCT BLOCK
always @(posedge aclr or posedge clock) begin
    if (aclr) begin
        for (i = 0; i <= lpm_delay; i = i + 1)
            dffpipe[i] <= 0;
        q_reg <= 0;
    end else if (clock) begin
        if (lpm_delay > 0) begin
            for (i = lpm_delay-1; i > 0; i = i - 1)
                dffpipe[i] <= dffpipe[i - 1];
            q_reg <= dffpipe[lpm_delay - 1];
            dffpipe[0] <= d;
        end else begin
            q_reg <= d;
        end
    end
end

assign q = q_reg;

endmodule

