module top_module(
    input clk,
    input rd_en,
    input [0:0] E,
    input [0:0] Q,
    input [23:0] din,
    output reg [23:0] dout,  // Changed wire to reg
    output [11:0] count
);// Declare internal signals
    reg [23:0] mem [0:23];
    reg [11:0] wr_ptr = 0;
    reg [11:0] rd_ptr = 0;
    reg [11:0] cnt = 0;
    reg [11:0] next_wr_ptr = 0;
    reg [11:0] next_rd_ptr = 0;
    reg [11:0] next_cnt = 0;
    wire mem_full = (cnt == 24);
    wire mem_empty = (cnt == 0);

    // Write logic
    always @ (posedge clk) begin
        if (E) begin
            next_wr_ptr = wr_ptr + 1;
            if (next_wr_ptr == 24) begin
                next_wr_ptr = 0;
            end
            if (!mem_full) begin
                mem[wr_ptr] <= din;
                next_cnt = cnt + 1;
            end
        end
    end

    // Read logic
    always @ (posedge clk) begin
        if (Q) begin
            next_rd_ptr = rd_ptr + 1;
            if (next_rd_ptr == 24) begin
                next_rd_ptr = 0;
            end
            if (!mem_empty && rd_en) begin
                dout <= mem[rd_ptr]; // Assignment to dout remains valid now
                next_cnt = cnt - 1;
            end
        end
    end

    // Update state
    always @ (posedge clk) begin
        wr_ptr <= next_wr_ptr;
        rd_ptr <= next_rd_ptr;
        cnt <= next_cnt;
    end

    // Output count
    assign count = cnt;

endmodule

module top_module(
    input clk,
    input reset,
    input [7:0] in,
    output reg [9:0] out,
    output reg red,
    output reg yellow,
    output reg green
);reg [8:0] parity_check;
reg [2:0] priority_enc;

always @(posedge clk) begin
    if (reset) begin
        parity_check <= 0;
        priority_enc <= 0;
        out <= 0;
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        parity_check <= {in, 1'b0} ^ parity_check;
        priority_enc <= {1'b0, in} > priority_enc;
        out <= {priority_enc, parity_check};
        red <= ~parity_check[8];
        yellow <= priority_enc != 0;
        green <= parity_check[8];
    end
end

endmodule

