description:
Design a 4-bit wide bit-reversing circuit. The module takes a 4-bit input and outputs the bits in reverse order. For example, if the input is `in[3:0]`, the output will be `out[3:0]`, where `out[0]` will be `in[3]`, `out[1]` will be `in[2]`, `out[2]` will be `in[1]`, and `out[3]` will be `in[0]`.
module top_module(
    in,
    out
);

code:
module top_module(
    in,
    out
);input [3:0] in;
    output [3:0] out;

    wire a, b, c, d;

    // Reverse the bits
    assign a = in[0] & ~in[1] & ~in[2] & ~in[3];
    assign b = ~in[0] & in[1] & ~in[2] & ~in[3];
    assign c = ~in[0] & ~in[1] & in[2] & ~in[3];
    assign d = ~in[0] & ~in[1] & ~in[2] & in[3];

    // Output the reversed bits
    assign out = {d, c, b, a};

endmodule

