module traffic_light_controller (
        input clk,
        input areset,
        input walk_request,
        output reg red_light,
        output reg green_light);parameter Red=2'b01, Green=2'b10;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Red;
		else
			state <= next_state;
	end

	always @(*) begin
		case (state)
			Red: if (walk_request && counter == 5) next_state = Green;
				 else next_state = Red;
			Green: if (counter == 10) next_state = Red;
				   else next_state = Green;
			default: next_state = Red;
		endcase
	end

	always @(posedge clk, posedge areset) begin
		if (areset)
			counter <= 0;
		else if (state == Red && walk_request)
			counter <= counter + 1;
		else if (state == Green)
			counter <= counter + 1;
		else
			counter <= 0;
	end

	assign red_light = (state == Red);
	assign green_light = (state == Green);

endmodule

